import{_ as t,o as i,c as o,ae as a}from"./chunks/framework.C6cq5ZWr.js";const n="/DocumentationLivePage/assets/image_1.IzSkWPq5.png",r="/DocumentationLivePage/assets/image_2.CfSplpRf.png",s="/DocumentationLivePage/assets/image_3.DR0z8OZv.png",l="/DocumentationLivePage/assets/image_4.CAgXLrOO.png",g="/DocumentationLivePage/assets/image_5.v2vwJ9Mi.png",h="data:image/png;base64,",u="/DocumentationLivePage/assets/image_7.CAM-2qdO.png",c="/DocumentationLivePage/assets/image_8.D0nGmycT.png",m="/DocumentationLivePage/assets/image_9.rcnG_sUb.png",p="/DocumentationLivePage/assets/image_10.uqJ8Pc-L.png",d="/DocumentationLivePage/assets/image_11.CtFRznah.png",f="/DocumentationLivePage/assets/image_12.Dg7npJ5u.png",v="/DocumentationLivePage/assets/image_13.DKTkye9a.png",b="/DocumentationLivePage/assets/image_14.Dl0QuQls.png",A="/DocumentationLivePage/assets/image_15.DMmMkv9A.png",T="/DocumentationLivePage/assets/image_16.D84RKdi8.png",w="/DocumentationLivePage/assets/image_17.CdCXe1IA.png",P="/DocumentationLivePage/assets/image_18.Dy8Pzzyb.png",y="/DocumentationLivePage/assets/image_19.DZ8K4vM9.png",D="/DocumentationLivePage/assets/image_20.CGg6OIlM.png",C="/DocumentationLivePage/assets/image_21.qdjs_-ZG.png",S="/DocumentationLivePage/assets/image_22.B-vaTALe.png",L="/DocumentationLivePage/assets/image_23._2vABc3E.png",k="data:image/png;base64,",I="data:image/png;base64,",R="data:image/png;base64,",_="/DocumentationLivePage/assets/image_27.B35GFjP3.png",E="/DocumentationLivePage/assets/image_28.C-alW1pj.png",x="/DocumentationLivePage/assets/image_29.DKTb3-oB.png",M="/DocumentationLivePage/assets/image_30.CLZLBvFA.png",B="/DocumentationLivePage/assets/image_31.Dze1ca5A.png",j="/DocumentationLivePage/assets/image_32.D-UTEeos.png",U="/DocumentationLivePage/assets/image_33.CI3Ze4Lk.png",F="/DocumentationLivePage/assets/image_34.DspwSM2_.png",G="/DocumentationLivePage/assets/image_35.CWC0ctJw.png",q="/DocumentationLivePage/assets/image_36.B39uW6QP.png",O="/DocumentationLivePage/assets/image_37.ClVvi7RV.png",Q="/DocumentationLivePage/assets/image_38.8nG7bV4U.png",H="/DocumentationLivePage/assets/image_39.DWtIlluG.png",N="/DocumentationLivePage/assets/image_40.BymBlUXK.png",z="/DocumentationLivePage/assets/image_41.Bfnhqy4y.png",W="/DocumentationLivePage/assets/image_42.B0lIZcE4.png",V="/DocumentationLivePage/assets/image_43.CvfdVzTl.png",Y="/DocumentationLivePage/assets/image_44.BbZ9PtwL.png",K="/DocumentationLivePage/assets/image_45.ez3G8KAN.png",Z="/DocumentationLivePage/assets/image_46.DLq2vWxB.png",J="/DocumentationLivePage/assets/image_47.CgLNd1yK.png",X="/DocumentationLivePage/assets/image_48.DrhMWFud.png",$="/DocumentationLivePage/assets/image_49.C5qUDteF.png",ee="/DocumentationLivePage/assets/image_50.CUe5sChd.png",te="/DocumentationLivePage/assets/image_51.hPwtBiuq.png",ie="/DocumentationLivePage/assets/image_52.BQ-SM22L.png",oe="/DocumentationLivePage/assets/image_53.DjF9qsvg.png",ae="/DocumentationLivePage/assets/image_54.DTB0ev1e.png",ne="/DocumentationLivePage/assets/image_55.q5IooDue.png",re="/DocumentationLivePage/assets/image_56.C_U3jSZO.png",se="/DocumentationLivePage/assets/image_57.y9zDUPGW.png",le="/DocumentationLivePage/assets/image_58.DJ3tpgU4.png",ge="/DocumentationLivePage/assets/image_59.BkzzEGlV.png",be=JSON.parse('{"title":"Advanced AI Turret Framework","description":"","frontmatter":{},"headers":[],"relativePath":"unreal/advanced-ai-turret-framework/index.md","filePath":"unreal/advanced-ai-turret-framework/index.md"}'),he={name:"unreal/advanced-ai-turret-framework/index.md"};function ue(ce,e,me,pe,de,fe){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="advanced-ai-turret-framework" tabindex="-1">Advanced AI Turret Framework <a class="header-anchor" href="#advanced-ai-turret-framework" aria-label="Permalink to &quot;Advanced AI Turret Framework&quot;">​</a></h1><p>Advanced AI Turret Framework</p><p><img src="'+n+'" alt=""></p><h1 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h1><ul><li>The Advanced AI Turret Framework is perfect for games with multiple robot AI enemies. It is built entirely in C++ and is easy to set up.</li><li>Simply set the parameters for your game, drag and drop the Turret, and it will work.</li><li>For AI detection of your pawn, the Player Controller and Character must be derived from our Custom Player Controller and Custom Player Character classes.</li><li>Or implement the IGenericTeamAgentInterface properly, Team <a href="#_heading=h.vcv9efh0qkt8">Agent Interface Setup Guide</a> in both their controller and character classes.</li><li>And add “AIPerception Stimuli Source”</li><li><img src="'+r+'" alt=""></li></ul><p>And also make sure you’ve registered the required sources for senses too.</p><p><img src="'+s+'" alt=""></p><ul><li>This allows you to create AI teams that can fight each other.</li></ul><p>For Setup, refer to the 10-point setup guide.</p><h1 id="setup-guide" tabindex="-1"><strong>Setup Guide</strong> <a class="header-anchor" href="#setup-guide" aria-label="Permalink to &quot;**Setup Guide**&quot;">​</a></h1><h2 id="installation-guide" tabindex="-1"><strong>Installation Guide</strong> <a class="header-anchor" href="#installation-guide" aria-label="Permalink to &quot;**Installation Guide**&quot;">​</a></h2><ul><li>Install the Plugin from Epic Launcher</li><li>Open your project</li><li>In the Edit menu, Select Plugins</li></ul><p><img src="'+l+'" alt=""></p><ul><li>Find and Enable the <strong>AdvancedAlTurretFramework Plugin</strong></li></ul><p><img src="'+g+'" alt=""></p><ul><li>Open the Content Browser</li></ul><p><img src="'+h+'" alt=""></p><ul><li>Open the Settings option in Content Browser and check on the Show C++ Classes and Show Plugin Content.</li></ul><p><img src="'+u+'" alt=""></p><h2 id="turret-base-body-setup-guide" tabindex="-1"><strong>Turret Base Body Setup Guide</strong> <a class="header-anchor" href="#turret-base-body-setup-guide" aria-label="Permalink to &quot;**Turret Base Body Setup Guide**&quot;">​</a></h2><ul><li>Go to the <strong>AdvancedAlTurretFrameworkContent/AITurret/Blueprint</strong></li></ul><p><strong><img src="'+c+'" alt=""></strong></p><ul><li>Drag and drop any turret with an attachment into the world, then set the parameters in the Turret Settings section of the details panel.</li></ul><p><img src="'+m+'" alt=""></p><ol><li><strong>Base Stats of the Turret</strong><ol><li><strong>Turret Speed</strong>: Defines the Movement speed of the Turret</li><li><strong>Wait Time</strong>: The Time to wait after reaching the patrol point</li><li><strong>Acceptable Radius</strong>: Fixed Distance added to the threshold between AI and the Target location. AI will stop following the player as long as it’s in an Acceptable radius</li><li><strong>Total Health</strong>: Max health of the Turret</li></ol></li><li><strong>Turret Movement</strong>: <ol><li><strong>Movement Mode</strong>: <ol><li><strong>Mobile</strong>: Can move around and follow the Target</li><li><strong>Mounted</strong>: Stationary Turret <ol><li><strong>Fixed-Fire Mode</strong>: This mode emphasizes the Turret’s fixed direction, indicating that it will only fire enemies within its predefined field of vision.</li><li><strong>Tracking-Fire Mode</strong>: This mode highlights the Turret’s ability to track and follow enemies, ensuring that it keeps them in sight and continuously engages.</li></ol></li></ol></li><li><strong>Movement Behaviour</strong>: <ol><li><strong>Patrol Type</strong>: Set the locations of patrol points in the “Array of Points” vector. <ol><li><strong>Sequence</strong>: Turret will move around the patrol Points in the sequence it was assigned to</li><li><strong>RandomPoints</strong>: Turret will move around the Patrol Points in a random order</li></ol></li></ol></li></ol></li></ol><p><img src="'+p+'" alt=""></p><ul><li><ul><li><ol><li><strong>Radius Type</strong>: The turret will patrol in the given radius from a given center. When following the target, if the target goes out of the defined radius, the turret will try to get close to the Target while staying within the radius.</li></ol></li></ul></li></ul><p><img src="'+d+'" alt=""></p><ol><li><strong>Search Center</strong>: The center of the Search area, using this location Turret will patrol the area of the defined radius.</li><li><strong>Offset:</strong> When the player leaves the search area, the Turret adjusts its acceptable radius to get as close as possible without being too near the border. The <strong>Offset</strong> value keeps the Turret slightly away from the edge, ensuring it&#39;s not too close if the player is just outside.</li><li><strong>Search Radius:</strong> Radius of the Patrol Area of the Turret <ul><li><ol><li><strong>Investigate Type</strong>:</li></ol></li></ul></li></ol><ul><li>The movement of the Turret in this Movement Behaviour is similar to the Radius search, though the turret will come out of the radius when following the Target, and the Turret can hear sounds in this movement behavior only.</li><li>Upon detecting the sound Turret will go to that position and will patrol <em>n</em> times around the area where the sound was detected, and after that it will go back to its usual patrolling.</li><li>If the position is unreachable, it will ignore the detected sound.</li><li>The sound can be made by calling the report Noise event in the Target.</li><li>If the value of loudness is too much, it can be detected by the Turret even if it&#39;s outside its hearing range. If the loudness value in the Report Noise Event is high, it can be heard by the AI even outside its hearing range. Try to keep it around 1-5.</li></ul><p><img src="'+f+'" alt=""></p><p><img src="'+v+'" alt=""></p><p>Set the Hearing-related properties in the AI Perception category.</p><p><strong>Search Center</strong> and <strong>Search Radius</strong> are the same as the ones in <strong>Radial Search</strong>.</p><ol><li><strong>AI Perception Settings:</strong></li></ol><p><img src="'+b+'" alt=""></p><ol><li><strong>Hearing Range</strong>: The range in which AI can hear noise</li><li><strong>Radius</strong>: The radius of the area in which the Turret will patrol at the location of the noise.</li><li><strong>Search Count</strong>: The number of locations the turret should patrol near the location of the noise.</li></ol><p><strong>The above properties will only be visible in the Investigate Type Movement Behaviour.</strong></p><ol><li><strong>Sight Settings</strong><ol><li><strong>Sight Radius</strong>: Maximum sight distance to notice the target.</li><li><strong>Lose Sight Radius</strong>: Maximum sight distance to see the target that has already been seen.</li><li><strong>Peripheral Vision Half Angle Degrees</strong>: How far to the side AI can see, in degrees. The value represents the angle measured with the forward vector, not the whole range.</li></ol></li></ol><h2 id="turret-attachment-setup-guide" tabindex="-1"><strong>Turret Attachment Setup Guide</strong> <a class="header-anchor" href="#turret-attachment-setup-guide" aria-label="Permalink to &quot;**Turret Attachment Setup Guide**&quot;">​</a></h2><ul><li>After setting the Base parameters, select the Attachment Component from the hierarchy to set its parameters in the details panel.</li></ul><p><img src="'+A+'" alt=""></p><p>To add any attachment to the BP Turret, click on the Add button in the components window.</p><p><img src="'+T+'" alt=""></p><p>Search for the attachment you want to add and click on it to add it.</p><p><img src="'+w+'" alt=""></p><p>Make sure the attachment component is the child of the skeletal mesh of the Turret.</p><p><img src="'+P+'" alt=""></p><p>Now, attach the mesh of attachment with that of the Turret</p><p>In the details panel, in the socket section.</p><p><img src="'+y+'" alt=""></p><p>Set the Parent socket to “<strong>attach_root”</strong> bone to directly attach the component.</p><p>There are a total 6 Types of <strong>Attachments</strong>:</p><ul><li><strong>Gun Attachment</strong></li><li><strong>Rocket Launcher</strong></li><li><strong>Grenade Launcher</strong></li><li><strong>Bomber</strong></li><li><strong>Laser Shooter</strong></li><li><strong>Mine Placer</strong></li></ul><p>There are some common properties among the attachments:</p><ul><li><strong>Projectile Actor</strong>: The actor spawns when firing. This property is only visible in the Gun, Grenade launcher, and Rocket Launcher Attachments.</li><li><strong>Base Effects</strong>: Niagara Particles VFX for muzzle flash in Attachments, excluding bomber and Mine Placer.</li><li><strong>Attachment Properties</strong>:</li></ul><p><img src="'+D+'" alt=""></p><ul><li><ul><li><strong>Fire Rate</strong>: Rate of fire of the Turret.</li><li><strong>ShootTrace Channel</strong>: The turret will do the trace on the collision channel set here.</li><li><strong>Initial Delay</strong>: Time to wait when shooting the Target for the first time until it&#39;s in sight.</li><li><strong>Shooter Socket Name</strong>: The socket name at the bone from where the projectile/ laser beam will spawn.</li><li><strong>Indicator Parameter Name</strong>: Name of the parameter of the Material Instance for the Indication lights.</li><li><strong>Attack mode</strong>: <ul><li><strong>Lock on</strong>: Locks the target and will keep on attacking it until it&#39;s dead or unable to be detected by the turret.</li><li><strong>Closer to AI</strong>: The Turret will start attacking those who are closer to the turret.</li><li><strong>Attacker Priority</strong>: The turret will prioritize the targets that are damaging the turret.</li></ul></li></ul></li><li><strong>Projectile Properties</strong>:</li></ul><p><img src="'+C+'" alt=""></p><ul><li><ul><li><strong>Projectile Lifespan</strong>: Lifespan of the projectile.</li><li><strong>Should Override Projectile</strong>: When set to true, you will be able to change the base properties of Projectiles from here.</li><li><strong>Projectile Speed</strong>: Speed of the projectile in cm/s.</li><li><strong>Projectile gravity Scale</strong>: Gravity Multiplier to be applied to the projectile.</li><li><strong>Note:</strong> To allow the projectile to interact with environment assets such as doors, walls, etc. Make sure to check <strong>“Generate Overlap Events ”</strong> in the collision section, and also set the <strong>Collision Preset to “Default”.</strong></li></ul></li><li><strong>Damage Properties</strong>: <ul><li><strong>Damage Type Class</strong>: The class that helps the turret to deal special damage i.e., Fire, poison.</li><li><strong>Damage</strong>: The Amount of Damage to be dealt in a single hit.</li></ul></li></ul><p><strong>The following properties are only accessible in Attachments that deal damage through Explosions</strong>.</p><ul><li><ul><li><strong>Damage Inner Radius</strong>: Radius of the full damage area from the origin.</li><li><strong>Damage Falloff</strong>: Falloff exponent to be applied when dealing damage radially.</li><li><strong>Minimum Damage</strong>: Minimum amount of Damage to be done by the turret.</li><li><strong>Damage outer Radius</strong>: Radius of the minimum damage area from the origin.</li></ul></li></ul><ol><li><strong>Gun Attachment</strong>:</li></ol><p><img src="'+S+'" alt=""></p><ul><li><strong>Gun Mode</strong>: <ul><li><strong>Single</strong>:</li></ul></li></ul><p><img src="'+L+'" alt=""></p><ul><li><ul><li><ul><li><strong>WaitTime</strong>: Time to wait before firing the next bullet.</li><li><strong>Magazine Size</strong>: Number of bullets in a magazine.</li><li><strong>Reload Time</strong>: Time taken to reload.</li></ul></li><li><strong>Burst</strong></li></ul></li></ul><p><img src="'+k+'" alt=""></p><ul><li><ul><li><ul><li>The number of bullets to shoot in a single burst.</li></ul></li><li><strong>Auto</strong></li></ul></li></ul><p><img src="'+I+'" alt=""></p><ul><li><ul><li><ul><li>How far the bullet can travel in cms.</li></ul></li></ul></li></ul><ol><li><strong>RocketLauncher</strong>:</li></ol><p><img src="'+R+'" alt=""></p><ul><li>These two properties are exclusive to the Rocket launcher only, and ShouldOverride Projectile should be true to access these in the details panel.</li><li><strong>isHoming</strong>: When True, the projectile will follow the target until it expires or hits something.</li><li><strong>Homing Magnitude</strong>: The accuracy of the Homing Rocket.</li></ul><ol><li><strong>Laser Shooter</strong>:</li></ol><p><img src="'+_+'" alt=""></p><ul><li><strong>Laser beam</strong>: Particle System of Laser beam to visualize laser shooting</li><li><strong>Base Damage</strong>: Base Damage is to be dealt at the First hit of the beam.</li><li><strong>Laser Damage Type</strong>: This will decide the type of damage you want to deal to the player. <ul><li><strong>Constant Damage</strong>: Constant Damage at every hit.</li></ul></li></ul><p><img src="'+E+'" alt=""></p><ul><li><ul><li><strong>Rate of Damage Over Time</strong>: Damage accruing at a compound rate. <ul><li><strong>Damage Rate</strong>: Rate of Damage to be increased over time.</li><li><strong>Max Damage</strong>: The damage will keep on increasing until it is equal to that of Max Damage.</li></ul></li></ul></li></ul><p><img src="'+x+'" alt=""></p><ul><li><ul><li><strong>Damage Curve</strong>: It will use a curve to deal the damage at that given time. <ul><li><strong>Damage Curve</strong>: The float curve graph is used to calculate the amount of damage at a specific time.</li></ul></li></ul></li></ul><p><img src="'+M+'" alt=""></p><ul><li><ul><li><strong>Laser Range</strong>: Indicates the current range of the laser. This value is visible in the editor for reference, but can only be modified at runtime using the provided methods. These methods are accessible both via Blueprints and in C++. <ul><li><strong>Enabled</strong>: When enabled, the laser&#39;s range will be limited. The specific range can be adjusted dynamically at runtime using the appropriate methods.</li><li><strong>Disabled</strong>: When disabled, the laser will operate without a range limit, effectively allowing it to extend indefinitely or until it hits an obstruction, depending on the system&#39;s behavior.</li></ul></li></ul></li></ul><p><strong><img src="'+B+'" alt=""></strong></p><p><strong><img src="'+j+'" alt=""></strong></p><ol><li><strong>Bomber</strong>:</li></ol><p>The bomber will rush towards the target when it sees one and will try to make contact with the target. When the bomber makes contact after some time, the bomb will explode.</p><p><img src="'+U+'" alt=""></p><ul><li><strong>Timer</strong>: The time taken to explode after coming in contact with the player. If set to 0, the bomber will instantly explode.</li><li>The rest of the properties are the same as those mentioned in the Damage Properties section above.</li></ul><p>There’s a collision sphere attached to the attachment component. If that sphere overlaps with the target, the timer will start ticking and it will explode after a certain time. The collision sphere properties can be found in the base properties category inside Attachment Settings.</p><p><img src="'+F+'" alt=""></p><ol><li><strong>Mine Placer</strong>:</li></ol><p>Mine Placer will not be able to see the player, its only job is to place a certain number of mines in the assigned area. When AI is done placing all the mines, it will start roaming until a mine gets destroyed. Mine Placer will roam around the area as if it’s patrolling, and whenever it reaches the patrol point, it will spawn the defined number of mines and spread them out, and then move to the next location. The Damage Properties of the Mine are the same as the other damage properties of explosives. Currently, there are only two types of mines created.</p><ul><li><strong>Proximity Mine</strong>: If the player is at a distance of a certain radius from the mine, it will explode.</li><li><strong>Land Mine</strong>: If the player comes in contact with the mine, it will explode.</li></ul><p><img src="'+G+'" alt=""></p><ul><li><strong>Mine Count</strong>: Number of mines to be spawned at once.</li><li><strong>SpawnZ</strong>: Offset Position in the Z Axis of the Attachment from where the mine should be thrown.</li><li><strong>Throwable Actor</strong>: Blueprint Actor reference of the mines.</li><li><strong>Total Mine</strong>: Total Mine count that should be placed by the mine placer.</li><li>This is how to set up the Turret in your level.</li><li>You can create the Projectile Actors that you want, but they should be derived from the ProjectileParent Class same goes for the Mines they are derived from the ThrowableParent Class.</li><li>It is advised to add a custom collision trace channel through the project settings so that all the damage dealt by the turret can be done using that, and it doesn&#39;t get interrupted by any other collision.</li></ul><h2 id="collision-channel-setup-guide" tabindex="-1"><strong>Collision Channel Setup Guide</strong> <a class="header-anchor" href="#collision-channel-setup-guide" aria-label="Permalink to &quot;**Collision Channel Setup Guide**&quot;">​</a></h2><ul><li><strong>Note</strong>: Either create a new Trace Channel or use a previously created Trace channel, but it is <strong>necessary</strong> to add that channel in variable</li></ul><p>ShootTrace Channel under the AttachmentComponent.</p><p><img src="'+q+'" alt=""></p><p>And set the trace channel’s response to Block in Character’s mesh Component. <strong>Without this Turret won’t deal damage to the Player.</strong></p><ul><li>To add a custom Trace channel, go to the Project Settings from the Edit Menu.</li></ul><p><img src="'+O+'" alt=""></p><ul><li>After that, select the Collision option from the categories on the right, you can find it under the Engine Section.</li></ul><p><img src="'+Q+'" alt=""></p><ul><li>Then click on the New Trace Channel button to create the new trace channel.</li></ul><p><img src="'+H+'" alt=""></p><ul><li>Set its default collision response for other objects, and you are good to go. Use this newly created Trace in the ShootTrace Channel variable in the Attachments, and set the collision response of this channel accordingly in your character. The process is the same for creating a new Object Channel. <strong>NOTE</strong>: NE_BulletTrail and NE_LaserBeam Niagara emitter works on collision, so don&#39;t forget to change the trace channel there too.</li></ul><h3 id="turret-collision-setup" tabindex="-1"><strong>Turret Collision Setup</strong> <a class="header-anchor" href="#turret-collision-setup" aria-label="Permalink to &quot;**Turret Collision Setup**&quot;">​</a></h3><ul><li>In TurretBase for “Mesh” component</li></ul><p><img src="'+N+'" alt=""> <img src="'+z+'" alt=""></p><ul><li>In BP_TurretBase, for DetectionSphere</li></ul><p><img src="'+W+'" alt=""><img src="'+V+'" alt=""></p><h3 id="projectile-collision-setup" tabindex="-1"><strong>Projectile Collision Setup</strong> <a class="header-anchor" href="#projectile-collision-setup" aria-label="Permalink to &quot;**Projectile Collision Setup**&quot;">​</a></h3><ul><li>For Grenade and Rockets, use the inbuilt collision preset “OverlapAll”</li><li>For Landmine’s Box Collision,</li></ul><p><img src="'+Y+'" alt=""></p><p><img src="'+K+'" alt=""></p><ul><li>For Landmine’s Mesh Collision</li></ul><p><img src="'+Z+'" alt=""><img src="'+J+'" alt=""></p><ul><li>For Proximity Mine’s Box Collision</li></ul><p><img src="'+X+'" alt=""></p><p><img src="'+$+'" alt=""></p><ul><li>For Proximity Mine’s Proximity Area</li></ul><p><img src="'+ee+'" alt=""></p><p><img src="'+te+'" alt=""></p><ul><li>For Proixmity Mine’s Mesh Collision</li></ul><p><img src="'+ie+'" alt=""></p><p><img src="'+oe+'" alt=""></p><h3 id="turret-enemy-character-collision-setup" tabindex="-1"><strong>Turret Enemy Character Collision Setup</strong> <a class="header-anchor" href="#turret-enemy-character-collision-setup" aria-label="Permalink to &quot;**Turret Enemy Character Collision Setup**&quot;">​</a></h3><ul><li>For the Turret enemy Character, this setup should be used for proper behaviour with the turret.</li></ul><p><img src="'+ae+'" alt=""></p><p><img src="'+ne+'" alt=""></p><h2 id="team-agent-interface-setup-guide" tabindex="-1"><strong>Team Agent Interface Setup Guide</strong> <a class="header-anchor" href="#team-agent-interface-setup-guide" aria-label="Permalink to &quot;**Team Agent Interface Setup Guide**&quot;">​</a></h2><ul><li>To set up IGenericTeamAgentInterface, your character class must be in C++ as IGenericTeamAgentInterface is not a blueprintable interface. <ul><li><p>First, you need to implement the interface in your Character class like this. <img src="'+re+'" alt=""></p></li><li><p>Then, override the functions from that interface. <img src="'+se+'" alt=""> Also, write the definitions like this. <img src="'+le+'" alt=""></p></li><li><p>Create a variable of Type FGenericTeamID. <img src="'+ge+'" alt=""></p></li></ul></li><li>And with this, you are good to go!</li></ul>',134)])])}const Ae=t(he,[["render",ue]]);export{be as __pageData,Ae as default};
